// Re-exported, not re-implemented: the arithmetic moved to `utils/range` when the
// component's own budget line was ratified, and `@standarui/core/slider` keeps
// naming it. `../../*` is external to the component's bundle, so the bytes went
// with it — they are budgeted on the `range arithmetic` line instead.
export {
  constrainValue,
  fromPercent,
  getPercentFromPoint,
  normalizeValues,
  resolveLargeStep,
  resolveMarks,
  roundToPrecision,
  setValueAtIndex,
  snapToStep,
  toPercent,
  toValueArray,
} from "../../utils/range";
export { anatomy, parts, type SliderPart } from "./slider.anatomy";
export { connect } from "./slider.connect";
export {
  getControlEl,
  getControlId,
  getHiddenInputId,
  getLabelId,
  getRootEl,
  getRootId,
  getThumbEl,
  getThumbId,
  hasPart,
} from "./slider.dom";
export { machine } from "./slider.machine";
export { getKeyIntent, resolveDirection, toAdjustEvent } from "./slider.props";
export type {
  ResolvedSliderMachineProps,
  SliderAdjustEvent,
  SliderAdjustment,
  SliderAdjustmentKind,
  SliderApi,
  SliderIntent,
  SliderMachineProps,
  SliderMarkerProps,
  SliderMarks,
  SliderPointOptions,
  SliderRange,
  SliderSchema,
  SliderThumbAlignment,
  SliderThumbProps,
  SliderValueChangeDetails,
  SliderValueTextDetails,
} from "./slider.types";

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type SliderPart =
  | "root"
  | "label"
  | "valueText"
  | "control"
  | "track"
  | "range"
  | "thumb"
  | "hiddenInput"
  | "markerGroup"
  | "marker";

export const anatomy: Anatomy<SliderPart> = createAnatomy("slider").parts(
  "root",
  "label",
  "valueText",
  "control",
  "track",
  "range",
  "thumb",
  "hiddenInput",
  "markerGroup",
  "marker",
);

export const parts: Record<SliderPart, AnatomyPart> = anatomy.build();

export interface SliderCssVars {
  // --- written ---
  /** Position of the value on the track. */
  "--sui-slider-percent": "<percentage>";
  /** Where the filled range starts. */
  "--sui-slider-range-start": "<percentage>";
  /** Where the filled range ends. */
  "--sui-slider-range-end": "<percentage>";
  /** Position of one thumb on the track. */
  "--sui-slider-thumb-percent": "<percentage>";
  /** Position of one marker on the track. */
  "--sui-marker-percent": "<percentage>";
}

import { ariaAttr, dataAttr } from "../../dom/attrs";
import { resolveDir } from "../../dom/text-dir";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { roundToPrecision, toPercent, toValueArray } from "../../utils/range";
import { parts } from "./slider.anatomy";
import {
  getControlEl,
  getControlId,
  getHiddenInputId,
  getLabelId,
  getRootId,
  getThumbId,
} from "./slider.dom";
import { getKeyIntent, resolveDirection, toAdjustEvent } from "./slider.props";
import type { SliderApi, SliderMarkerProps, SliderSchema, SliderThumbProps } from "./slider.types";

/**
 * The core places percentages, the sheet does the layout. Rounded, so a third of a
 * track does not serialise seventeen digits into the markup — and so the server
 * and the client write the same string.
 */
function pct(ratio: number): string {
  return `${roundToPrecision(ratio * 100, 4)}%`;
}

export function connect<T extends PropTypes>(
  service: Service<SliderSchema>,
  normalize: NormalizeProps<T>,
): SliderApi<T> {
  const { context, prop, computed, state, send, scope } = service;

  const value = context.get("value");
  const valuePercent = computed("percent");
  const valueAsText = computed("valueAsText");
  const interactive = computed("isInteractive");

  const min = prop("min");
  const max = prop("max");
  const dir = prop("dir");
  const orientation = prop("orientation");
  const disabled = prop("disabled");
  const readOnly = prop("readOnly");
  const invalid = prop("invalid");

  const activeIndex = context.get("activeIndex");
  const dragging = activeIndex >= 0;
  const engaged = state.matches("engaged");
  const focusedIndex = context.get("focusedIndex");
  // Held from the moment focus landed, and only while it is still here — the same
  // rule every other control in the library follows.
  const focusSource = state.matches("focused", "engaged") ? context.get("focusSource") : null;
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  const lastIndex = value.length - 1;
  // One thumb fills from the floor; two fill between themselves. Both are written
  // as the same pair of custom properties, which is what makes `range-slider` a
  // preset later rather than a second component.
  const rangeStart = value.length > 1 ? (value[0] ?? min) : min;
  const rangeEnd = value[lastIndex] ?? min;

  const stateAttrs = {
    "data-orientation": orientation,
    "data-disabled": dataAttr(disabled),
    "data-readonly": dataAttr(readOnly),
    "data-invalid": dataAttr(invalid),
    "data-dragging": dataAttr(dragging),
    "data-engaged": dataAttr(engaged),
  };

  return {
    value,
    valuePercent,
    valueAsText,
    marks: computed("markValues"),
    dragging,
    engaged,
    disabled,
    focusedIndex,
    focusSource,
    focusVisible,

    setValue(next: number | readonly number[]): void {
      send({ type: "VALUE.SET", value: toValueArray(next, min) });
    },

    setValueAtIndex(index: number, next: number): void {
      const values = [...value];
      values[index] = next;
      send({ type: "VALUE.SET", value: values });
    },

    increment(index?: number): void {
      send({ type: "THUMB.INCREMENT", index: index ?? Math.max(focusedIndex, 0), large: false });
    },

    decrement(index?: number): void {
      send({ type: "THUMB.DECREMENT", index: index ?? Math.max(focusedIndex, 0), large: false });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        ...stateAttrs,
        id: getRootId(scope),
        dir,
        "data-thumb-alignment": prop("thumbAlignment"),
        style: { "--sui-slider-percent": pct(valuePercent[0] ?? 0) },
      }),

    // A `span`, not a `<label>`: `for` only names *labelable* elements, and a
    // `div[role="slider"]` is not one. The thumb points back with
    // `aria-labelledby` instead.
    getLabelProps: (): T["element"] =>
      normalize.element({ ...parts.label.attrs, ...stateAttrs, id: getLabelId(scope) }),

    getValueTextProps: (): T["element"] =>
      normalize.element({
        ...parts.valueText.attrs,
        ...stateAttrs,
        // The thumb already publishes the value through `aria-valuenow`; reading
        // the same number twice helps nobody.
        "aria-hidden": "true",
      }),

    getControlProps: (): T["element"] =>
      normalize.element({
        ...parts.control.attrs,
        ...stateAttrs,
        id: getControlId(scope),
        // The finger owns the axis for the length of the gesture; a scroll
        // container underneath must not take it away mid-drag.
        style: { touchAction: "none" },
      }),

    getTrackProps: (): T["element"] => normalize.element({ ...parts.track.attrs, ...stateAttrs }),

    getRangeProps: (): T["element"] =>
      normalize.element({
        ...parts.range.attrs,
        ...stateAttrs,
        // Whether the fill has a low *thumb* or a track edge for its leading side.
        // The percentages cannot say: `range-start` is 0% both for a lone thumb
        // and for a low thumb sitting on the minimum, and the sheet owes those two
        // different geometry — the first runs out to the track's edge, the second
        // stops on a knob's centre half a knob further in.
        "data-bounded": dataAttr(value.length > 1),
        style: {
          "--sui-slider-range-start": pct(toPercent(rangeStart, min, max)),
          "--sui-slider-range-end": pct(toPercent(rangeEnd, min, max)),
        },
      }),

    getThumbProps: ({ index }: SliderThumbProps): T["element"] => {
      const current = value[index] ?? min;
      const text = valueAsText[index] ?? "";
      const focused = focusedIndex === index;
      const active = dragging && activeIndex === index;

      return normalize.element({
        ...parts.thumb.attrs,
        ...stateAttrs,
        id: getThumbId(scope, index),
        role: "slider",
        // Dropped rather than set to -1: a disabled slider is out of the tab
        // order entirely, and a lone `tabindex="-1"` still answers a script's
        // `.focus()` as if it were reachable.
        tabIndex: disabled ? undefined : 0,
        "data-index": index,
        "data-dragging": dataAttr(active),
        "data-pressed": dataAttr(active),
        "data-engaged": dataAttr(engaged && focused),
        "data-focus-visible": dataAttr(focused && focusVisible),
        "data-focus-source": focused ? (focusSource ?? undefined) : undefined,
        // Narrowed to the neighbours as soon as there is more than one thumb:
        // that is what the user can actually reach.
        "aria-valuemin": index === 0 ? min : (value[index - 1] ?? min),
        "aria-valuemax": index === lastIndex ? max : (value[index + 1] ?? max),
        "aria-valuenow": current,
        // Only when the format adds something. On a bare 0→100 slider,
        // `valuenow=50` next to `valuetext="50"` makes some readers say "50, 50".
        "aria-valuetext": text === String(current) ? undefined : text,
        "aria-orientation": orientation,
        // Its own label part when there is one, the field's label otherwise. Never
        // both: two ids would read the same name twice.
        "aria-labelledby": context.get("hasLabel") ? getLabelId(scope) : prop("labelledBy"),
        "aria-describedby": prop("describedBy"),
        "aria-disabled": ariaAttr(disabled),
        "aria-readonly": ariaAttr(readOnly),
        // On the thumb, because the thumb is the `role="slider"` — a field that
        // marks itself invalid has to be heard on the element that owns the value,
        // the same place `checkbox`, `input`, `radio-group` and `switch` say it.
        "aria-invalid": ariaAttr(invalid),
        // Allowed on `role="slider"`, and an announcement rather than a
        // constraint: the submission is a `type="hidden"` input, which never
        // validates. It is here because the field around a required slider
        // already draws its asterisk, and nothing was saying it out loud.
        "aria-required": ariaAttr(prop("required")),
        style: { "--sui-slider-thumb-percent": pct(valuePercent[index] ?? 0) },

        onKeyDown(event) {
          if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
          // Shift+arrow carries no slider intent (research/input.md): consuming it
          // would take a text-selection gesture away from whatever owns one.
          if (event.shiftKey) return;
          const intent = getKeyIntent(event.key);
          // The interactive test sits before `preventDefault`, deliberately: on a
          // read-only slider PageDown still belongs to the page.
          if (intent === null || !interactive) return;
          event.preventDefault();
          // Resolved here rather than at the `dir` hoist in `connect`: with no
          // `dir` prop the answer is read off the track, and a DOM read at the
          // top of `connect` would run on the server.
          const keyDir = resolveDir(dir, getControlEl(scope));
          send(toAdjustEvent(resolveDirection(intent, keyDir, orientation), index));
        },

        onFocus(event) {
          if (!event.defaultPrevented) send({ type: "THUMB.FOCUS", index });
        },

        onBlur(event) {
          if (!event.defaultPrevented) send({ type: "THUMB.BLUR" });
        },
      });
    },

    /**
     * `type="hidden"`, not a hidden `<input type="range">`. A real range input
     * would bring form association *and* a second `role="slider"` into the
     * accessibility tree — two elements each claiming to hold the value, and
     * neutralising one with `aria-hidden` + `tabindex="-1"` hides the duplicate
     * without removing it. The thumb is the slider; this is the submission.
     */
    getHiddenInputProps: ({ index }: SliderThumbProps): T["input"] =>
      normalize.input({
        ...parts.hiddenInput.attrs,
        id: getHiddenInputId(scope, index),
        type: "hidden",
        name: prop("name"),
        form: prop("form"),
        // Native rule: a disabled control is not submitted.
        disabled,
        value: value[index] ?? min,
      }),

    getMarkerGroupProps: (): T["element"] =>
      normalize.element({
        ...parts.markerGroup.attrs,
        "data-orientation": orientation,
        "aria-hidden": "true",
      }),

    getMarkerProps: ({ value: mark }: SliderMarkerProps): T["element"] =>
      normalize.element({
        ...parts.marker.attrs,
        "data-orientation": orientation,
        "data-value": mark,
        // Neither design paints these two differently — the attribute exists so an
        // app can, and the default sheet renders them alike.
        "data-state":
          mark >= Math.min(rangeStart, rangeEnd) && mark <= Math.max(rangeStart, rangeEnd)
            ? "in-range"
            : "out-of-range",
        "data-disabled": dataAttr(disabled),
        style: { "--sui-marker-percent": pct(toPercent(mark, min, max)) },
      }),
  };
}

import { query } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

/**
 * Only the parts something points at get an id. `track`, `range`, `valueText` and
 * the markers are referenced by nothing — not by ARIA, not by the machine — and an
 * id per element the consumer never names is markup nobody reads.
 */
const COMPONENT = "slider";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLabelId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "label");
}

export function getControlId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "control");
}

export function getThumbId(scope: Scope, index: number): string {
  return getPartId(scope, COMPONENT, "thumb", String(index));
}

export function getHiddenInputId(scope: Scope, index: number): string {
  return getPartId(scope, COMPONENT, "hiddenInput", String(index));
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

/** The gesture surface: the pointer listeners and the rect both come from here. */
export function getControlEl(scope: Scope): HTMLElement | null {
  return scope.getById(getControlId(scope));
}

export function getThumbEl(scope: Scope, index: number): HTMLElement | null {
  return scope.getById(getThumbId(scope, index));
}

/**
 * `aria-labelledby` may only point at an id that exists — the rule `progress`,
 * `toggle-group` and `field` all follow, and the one an audit found broken in two
 * components because every fixture happened to render its label.
 */
export function hasPart(scope: Scope, part: string): boolean {
  return query(getRootEl(scope), `[data-part~="slider:${part}"]`) !== null;
}

/**
 * Three states, and each one earns its place.
 *
 * `engaged` is a state because it **owns an effect to unmount** — the intent scope
 * a gamepad's A button pushes (CDC §4.4). The drag is not a state: it has no
 * effect of its own, the pointer listeners are installed once at machine level
 * with pointer capture, and `activeIndex` in the context is enough to describe it.
 * Making the drag a state would also cost the focus: a thumb is dragged *and*
 * focused at the same time, and a flat machine cannot hold both.
 *
 * **The events carry a percentage, never a coordinate.** The pointer effect holds
 * the element, so it does the conversion; the machine stays DOM-free and every
 * transition is reachable from a node test. The switch already sends `progress`
 * rather than a `clientX` for the same reason.
 *
 * The effect order is a contract. `trackModality` first, because the handle has to
 * be held before the first Tab and its teardown must come last. `trackPointer`
 * last, so its own teardown — releasing the capture, dropping the click swallower
 * — runs before the modality refcount falls.
 */

import { addDomEvent, isPrimaryPointer } from "../../dom/event";
import { observeChildren } from "../../dom/observers";
import { resolveDir } from "../../dom/text-dir";
import { createMachine } from "../../machine/create-machine";
import type { Machine, PropAccessor, Transition } from "../../machine/types";
import { focusElement, getInputModality, pushEngageScope, trackInputModality } from "../../nav";
import type { Direction, InputModality } from "../../types";
import { isDev } from "../../utils/env";
import { arrayEquals } from "../../utils/equality";
import { warn } from "../../utils/invariant";
import {
  fromPercent,
  getPercentFromPoint,
  normalizeValues,
  resolveLargeStep,
  resolveMarks,
  setValueAtIndex,
  toPercent,
  toValueArray,
} from "../../utils/range";
import { getControlEl, getRootEl, getThumbEl, hasPart } from "./slider.dom";
import { resolveDirection, toAdjustEvent } from "./slider.props";
import type { SliderRange, SliderSchema } from "./slider.types";

/** How far the pointer has to travel before the click it leaves behind is eaten. */
const DRAG_THRESHOLD_PX = 4;

type Prop = PropAccessor<SliderSchema>;

function rangeOf(prop: Prop): SliderRange {
  return {
    min: prop("min"),
    max: prop("max"),
    step: prop("step"),
    minStepsBetweenThumbs: prop("minStepsBetweenThumbs"),
  };
}

/** The thumb a press belongs to — the nearest one, and 0 whenever there is one. */
function closestIndex(values: readonly number[], percent: number, prop: Prop): number {
  let best = 0;
  let closest = Number.POSITIVE_INFINITY;
  for (let index = 1; index < values.length; index++) {
    const distance = Math.abs(toPercent(values[index] ?? 0, prop("min"), prop("max")) - percent);
    if (distance < closest) {
      closest = distance;
      best = index;
    }
  }
  return best;
}

function hasAccessibleName(node: HTMLElement | null): boolean {
  // Absent is not nameless: nothing is rendered yet, and warning then would fire
  // on every server-rendered tree before its first paint.
  return (
    node === null ||
    node.hasAttribute("aria-label") ||
    node.hasAttribute("aria-labelledby") ||
    node.hasAttribute("title")
  );
}

/** One transition object, referenced by all four value events. */
const ADJUST: Transition<SliderSchema> = {
  guard: "isInteractive",
  actions: ["adjustValue", "invokeChangeEnd"],
};

/**
 * The same four events while a pad holds the thumb. Outside a hold every
 * adjustment *is* the whole gesture and commits on the spot; inside one the hold
 * is the gesture, and `THUMB.RELEASE` is its only end — so A, →, →, B has to
 * report once, not three times.
 */
const ADJUST_HELD: Transition<SliderSchema> = {
  guard: "isInteractive",
  actions: ["adjustValue"],
};

export const machine: Machine<SliderSchema> = createMachine<SliderSchema>({
  props({ props }) {
    const min = props.min ?? 0;
    const requestedMax = props.max ?? 100;
    warn(isDev() && requestedMax < min, `slider max ${requestedMax} is below min ${min}`);
    const max = Math.max(min, requestedMax);
    const requestedStep = props.step ?? 1;
    warn(isDev() && !(requestedStep > 0), `slider step must be positive, got ${requestedStep}`);
    const step = requestedStep > 0 ? requestedStep : 1;

    return {
      orientation: "horizontal",
      minStepsBetweenThumbs: 0,
      thumbAlignment: "contain",
      disabled: false,
      readOnly: false,
      invalid: false,
      required: false,
      // Pinned rather than read from the environment, for the same reason
      // `progress` pins it: a locale resolved from the browser makes the server
      // and the client format the same number differently, and hydration says so.
      locale: "en-US",
      formatOptions: {},
      intents: null,
      ...props,
      min,
      max,
      step,
      largeStep: resolveLargeStep(props.largeStep, min, max, step),
    };
  },

  context({ prop, bindable }) {
    return {
      value: bindable<number[]>(() => ({
        defaultValue: normalizeValues(
          toValueArray(prop("defaultValue"), prop("min")),
          rangeOf(prop),
        ),
        // Passed through rather than re-normalised on every read: a controlled
        // value belongs to the consumer, and `percent` clamps what it paints.
        value: prop("value") === undefined ? undefined : toValueArray(prop("value"), prop("min")),
        // Without this every write of a fresh array — which is every write — would
        // report a change and re-render, forever.
        isEqual: arrayEquals,
        onChange: (value) => prop("onValueChange")?.({ value }),
        debugLabel: "slider value",
      })),
      focusedIndex: bindable<number>(() => ({ defaultValue: -1 })),
      activeIndex: bindable<number>(() => ({ defaultValue: -1 })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
      hasLabel: bindable<boolean>(() => ({ defaultValue: false })),
    };
  },

  computed: {
    isInteractive: ({ prop }) => !prop("disabled") && !prop("readOnly"),
    percent: ({ context, prop }) =>
      context.get("value").map((value) => toPercent(value, prop("min"), prop("max"))),
    valueAsText({ context, prop }) {
      const getValueText = prop("getValueText");
      if (getValueText !== undefined) {
        return context.get("value").map((value, index) => getValueText({ value, index }));
      }
      const formatter = new Intl.NumberFormat(prop("locale"), prop("formatOptions"));
      return context.get("value").map((value) => formatter.format(value));
    },
    markValues: ({ prop }) => resolveMarks(prop("marks"), prop("min"), prop("max"), prop("step")),
  },

  refs() {
    return { thumbSize: null, entryValue: null };
  },

  // Pure: no DOM, no environment. The server renders what the client hydrates.
  initialState() {
    return "idle";
  },

  effects: ["trackModality", "trackParts", "trackPointer"],

  watch({ scope, track, action }) {
    // A dependency like any other, so an adapter that renders the label into
    // existence is in step immediately rather than one mutation record later.
    track(
      () => [hasPart(scope, "label")],
      () => action(["syncParts"]),
    );
  },

  on: {
    "VALUE.SET": { guard: "isInteractive", actions: ["setValue"] },
    "PARTS.SYNC": { actions: ["syncParts"] },
    "THUMB.FOCUS": { target: "focused", actions: ["setFocusedIndex", "captureFocusSource"] },
    "THUMB.BLUR": { target: "idle", actions: ["clearFocusSource"] },
    // `focusThumb` comes last, and it has to. Moving the focus fires a `focus`
    // event synchronously, the thumb's own handler answers it with `THUMB.FOCUS`,
    // and that re-entrant delivery replaces the event the actions still to run
    // were reading — so a press ordered focus-first writes no value at all.
    "CONTROL.PRESS": {
      guard: "isInteractive",
      actions: ["setFocusedIndex", "startDrag", "setValueFromPercent", "focusThumb"],
    },
    "THUMB.DRAG": { guard: "isDragging", actions: ["setValueFromPercent"] },
    // No `isInteractive` guard on purpose: a control that goes disabled halfway
    // through a gesture still has to finish it cleanly.
    "THUMB.DRAG_END": { actions: ["endDrag", "invokeChangeEnd"] },
    "THUMB.INCREMENT": ADJUST,
    "THUMB.DECREMENT": ADJUST,
    "THUMB.SET_MIN": ADJUST,
    "THUMB.SET_MAX": ADJUST,
  },

  states: {
    idle: {},

    focused: {
      effects: ["captureSelectIntent"],
      on: {
        "THUMB.ENGAGE": { guard: "canEngage", target: "engaged", actions: ["setFocusedIndex"] },
      },
    },

    /**
     * The snapshot is taken on entry and read on the way out. It is deliberately
     * *not* cleared on exit: the interpreter runs a state's exit actions before
     * the transition's own, so an exit that cleared it would erase the value B is
     * there to restore. Entry overwrites it, which is the same guarantee one step
     * later.
     */
    engaged: {
      entry: ["snapshotValue"],
      effects: ["captureEngageIntents"],
      on: {
        "THUMB.RELEASE": [
          {
            guard: ({ event }) => event.type === "THUMB.RELEASE" && event.committed,
            target: "focused",
            actions: ["clearSnapshot", "invokeChangeEnd"],
          },
          { target: "focused", actions: ["restoreValue", "invokeChangeEnd"] },
        ],
        // Carrying no target, these stay in `engaged` without re-entering it —
        // `snapshotValue` keeps the value the hold started on.
        "THUMB.INCREMENT": ADJUST_HELD,
        "THUMB.DECREMENT": ADJUST_HELD,
        "THUMB.SET_MIN": ADJUST_HELD,
        "THUMB.SET_MAX": ADJUST_HELD,
      },
    },
  },

  implementations: {
    guards: {
      isInteractive: ({ prop }) => !prop("disabled") && !prop("readOnly"),
      isDragging: ({ context }) => context.get("activeIndex") >= 0,
      canEngage: ({ prop }) => !prop("disabled") && !prop("readOnly") && prop("intents") !== null,
    },

    actions: {
      setValue({ context, prop, event }) {
        if (event.type !== "VALUE.SET") return;
        context.set("value", normalizeValues(event.value, rangeOf(prop)));
      },

      setValueFromPercent({ context, prop, event }) {
        if (event.type !== "CONTROL.PRESS" && event.type !== "THUMB.DRAG") return;
        const index = context.get("activeIndex");
        if (index < 0) return;
        const range = rangeOf(prop);
        const next = fromPercent(event.percent, range.min, range.max);
        context.set("value", setValueAtIndex(context.get("value"), index, next, range));
      },

      /**
       * All four value events land here. Out of range the write is a no-op, and
       * `isEqual` on the bindable means no `onValueChange` is reported either —
       * an arrow key held at the maximum stays silent.
       */
      adjustValue({ context, prop, event }) {
        if (!("index" in event)) return;
        const values = context.get("value");
        const current = values[event.index];
        if (current === undefined) return;
        const range = rangeOf(prop);
        const stride = "large" in event && event.large ? prop("largeStep") : range.step;
        const next =
          event.type === "THUMB.SET_MIN"
            ? range.min
            : event.type === "THUMB.SET_MAX"
              ? range.max
              : current + (event.type === "THUMB.DECREMENT" ? -stride : stride);
        context.set("value", setValueAtIndex(values, event.index, next, range));
      },

      startDrag({ context, event }) {
        if (event.type === "CONTROL.PRESS") context.set("activeIndex", event.index);
      },

      endDrag({ context }) {
        context.set("activeIndex", -1);
      },

      setFocusedIndex({ context, event }) {
        if ("index" in event) context.set("focusedIndex", event.index);
      },

      // APG: pressing anywhere on the track moves the value *and* the focus, so
      // the arrow keys carry on from where the pointer left off.
      focusThumb({ scope, event }) {
        if (event.type === "CONTROL.PRESS") focusElement(getThumbEl(scope, event.index));
      },

      // Read once, when focus lands, and held: the modality of `now` flips to
      // pointer after 300 ms of mouse movement whether or not the focus moved,
      // and a ring that blinks out under the user's hands was the result.
      captureFocusSource({ context, scope }) {
        context.set("focusSource", getInputModality(scope.getDoc()));
      },

      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },

      snapshotValue({ context, refs }) {
        refs.set("entryValue", [...context.get("value")]);
      },

      restoreValue({ context, refs }) {
        const entry = refs.get("entryValue");
        refs.set("entryValue", null);
        if (entry !== null) context.set("value", entry);
      },

      clearSnapshot({ refs }) {
        refs.set("entryValue", null);
      },

      invokeChangeEnd({ context, prop }) {
        prop("onValueChangeEnd")?.({ value: context.get("value") });
      },

      syncParts({ context, scope }) {
        context.set("hasLabel", hasPart(scope, "label"));
      },
    },

    effects: {
      // No listener: the source is read once, when focus lands, so a modality
      // change no longer has to reach every mounted control. Holding the handle
      // is the whole job — the tracker has to be running before the first Tab.
      trackModality({ scope }) {
        return trackInputModality(scope.getDoc());
      },

      trackParts({ scope, send }) {
        send({ type: "PARTS.SYNC" });
        // `role="slider"` demands an accessible name and the library cannot supply
        // one: with no label part rendered, only the consumer can. Same warning
        // shape as the dialog's nameless close trigger.
        //
        // Deferred a task, and it has to be: a slider inside a `field` is named by
        // the *field's* label, which reaches the thumb only once the field's own
        // observer has run — and effects run child before parent, so that is
        // strictly after this one. Warning from here would cry wolf on the very
        // composition the wiring exists to make correct.
        const timer = scope.getWin().setTimeout(() => {
          warn(
            isDev() && !hasPart(scope, "label") && !hasAccessibleName(getThumbEl(scope, 0)),
            "a slider has no accessible name — render its label part, or give the thumb an `aria-label`",
          );
        });
        const stop = observeChildren(getRootEl(scope), () => send({ type: "PARTS.SYNC" }));
        return () => {
          scope.getWin().clearTimeout(timer);
          stop();
        };
      },

      trackPointer({ scope, prop, refs, context, send }) {
        const control = getControlEl(scope);
        if (control === null) return;

        let pointerId: number | null = null;
        let moved = false;
        let startX = 0;
        let startY = 0;
        // Resolved once per gesture, unlike the rect. Without a `dir` prop the
        // answer comes from `getComputedStyle`, which forces a style recalc — and
        // a pointermove fires per frame, while the writing direction of a track
        // under the finger does not change mid-drag.
        let dragDir: Direction = "ltr";

        // The rect, by contrast, is read on every move rather than cached at
        // pointerdown: a scroll under the finger would invalidate a cached one and
        // the thumb would drift.
        const percentAt = (event: PointerEvent): number =>
          getPercentFromPoint(event.clientX, event.clientY, {
            rect: control.getBoundingClientRect(),
            orientation: prop("orientation"),
            dir: dragDir,
            thumbSize: refs.get("thumbSize") ?? 0,
          });

        const disposers = [
          addDomEvent(control, "pointerdown", (event: PointerEvent) => {
            if (pointerId !== null || !isPrimaryPointer(event)) return;
            if (prop("disabled") || prop("readOnly")) return;
            pointerId = event.pointerId;
            moved = false;
            startX = event.clientX;
            startY = event.clientY;
            dragDir = resolveDir(prop("dir"), control);
            // Measured once per gesture: under `contain` the centre of the thumb
            // travels a track shortened by one thumb, and the element is the only
            // place that width exists — the CSS owns it.
            const thumb = prop("thumbAlignment") === "center" ? null : getThumbEl(scope, 0);
            const box = thumb?.getBoundingClientRect();
            refs.set(
              "thumbSize",
              box === undefined ? 0 : prop("orientation") === "vertical" ? box.height : box.width,
            );
            const percent = percentAt(event);
            try {
              control.setPointerCapture(event.pointerId);
            } catch {
              // A pointer that is already gone still deserves the rest of the
              // sequence; capture is an optimisation, not a precondition.
            }
            // No text selection, no native image drag, no focus stolen by the
            // browser — `focusThumb` places it deliberately instead.
            event.preventDefault();
            send({
              type: "CONTROL.PRESS",
              percent,
              index: closestIndex(context.get("value"), percent, prop),
            });
          }),

          addDomEvent(control, "pointermove", (event: PointerEvent) => {
            if (event.pointerId !== pointerId) return;
            // The threshold gates the *click swallow*, never the value: a careful
            // two-pixel adjustment has to land.
            if (
              Math.abs(event.clientX - startX) >= DRAG_THRESHOLD_PX ||
              Math.abs(event.clientY - startY) >= DRAG_THRESHOLD_PX
            ) {
              moved = true;
            }
            send({ type: "THUMB.DRAG", percent: percentAt(event) });
          }),

          addDomEvent(control, "pointerup", (event: PointerEvent) => {
            if (event.pointerId !== pointerId) return;
            pointerId = null;
            // Browsers do not guarantee a final pointermove at the release point.
            send({ type: "THUMB.DRAG", percent: percentAt(event) });
            send({ type: "THUMB.DRAG_END", moved });
          }),

          addDomEvent(control, "pointercancel", (event: PointerEvent) => {
            if (event.pointerId !== pointerId) return;
            pointerId = null;
            send({ type: "THUMB.DRAG_END", moved });
          }),

          // A drag that ends on the track still produces a click. Swallowing it is
          // what keeps a consumer's own handler from acting on a gesture that was
          // never a click (precedent: switch).
          addDomEvent(
            control,
            "click",
            (event: MouseEvent) => {
              if (!moved) return;
              event.preventDefault();
              event.stopPropagation();
            },
            { capture: true },
          ),
        ];

        return () => {
          if (pointerId !== null) {
            try {
              control.releasePointerCapture(pointerId);
            } catch {
              // Already released by the browser — nothing left to hand back.
            }
          }
          for (const dispose of disposers.reverse()) dispose();
        };
      },

      /**
       * A is how a pad takes hold, and this is where it is claimed — while a thumb
       * is focused and nowhere else, so the scope is on the stack for exactly as
       * long as the grab is possible.
       *
       * Never from a keyboard. Enter on a slider belongs to the form around it,
       * the arrows already move the value without holding anything, and a keyboard
       * engage would hand Escape the power to rewind a value the user had settled
       * on. Read-only and disabled let the intent fall through untouched rather
       * than swallowing it into a state that would refuse it anyway.
       */
      captureSelectIntent({ prop, context, send }) {
        const host = prop("intents");
        if (host === null) return;
        return host.pushScope((event) => {
          if (event.intent !== "select" || event.source === "keyboard") return false;
          if (prop("disabled") || prop("readOnly")) return false;
          const index = context.get("focusedIndex");
          if (index < 0) return false;
          send({ type: "THUMB.ENGAGE", index });
          return true;
        });
      },

      /**
       * The gamepad's hold on the value. `pushEngageScope` consumes `back`, so B
       * restores the entry value instead of popping the layer underneath — a
       * slider inside a popover must not close the popover on the way out.
       *
       * The dispose it returns detaches silently: unmounting is not the user
       * letting go, so `onRelease` does not fire on teardown.
       */
      captureEngageIntents({ prop, context, scope, send }) {
        const host = prop("intents");
        if (host === null) return;
        return pushEngageScope(host, {
          onAdjust: (intent) => {
            const index = context.get("focusedIndex");
            if (index < 0) return;
            const dir = resolveDir(prop("dir"), getControlEl(scope));
            send(toAdjustEvent(resolveDirection(intent, dir, prop("orientation")), index));
          },
          onRelease: (committed) => send({ type: "THUMB.RELEASE", committed }),
        });
      },
    },
  },
});

/**
 * What the slider adds on top of the shared range arithmetic (`utils/range`):
 * turning an input — eight keys or a d-pad — into one of the four value events.
 *
 * **`Home`/`End` and the vertical axis never mirror.** RTL flips left/right and
 * nothing else: the APG says Home is *the minimum value*, not the left end, and
 * up/down have no writing order to follow. A keymap that mirrors wholesale breaks
 * both, which is why the mirror lives in exactly one function.
 */

import type { Direction, Orientation } from "../../types";
import type { SliderAdjustEvent, SliderAdjustment, SliderIntent } from "./slider.types";

/**
 * The mirror, in one place. `moveUp`/`moveDown`, `home`/`end` and the page keys
 * never reach the RTL branch — see the file header.
 */
export function resolveDirection(
  intent: SliderIntent,
  dir: Direction,
  orientation: Orientation,
): SliderAdjustment {
  const mirrored = orientation === "horizontal" && dir === "rtl";
  switch (intent) {
    case "moveRight":
      return { kind: mirrored ? "decrement" : "increment", large: false };
    case "moveLeft":
      return { kind: mirrored ? "increment" : "decrement", large: false };
    case "moveUp":
      return { kind: "increment", large: false };
    case "moveDown":
      return { kind: "decrement", large: false };
    case "pageUp":
      return { kind: "increment", large: true };
    case "pageDown":
      return { kind: "decrement", large: true };
    case "home":
      return { kind: "min", large: false };
    default:
      return { kind: "max", large: false };
  }
}

/** Written once so the keyboard and the engage scope cannot send different events. */
export function toAdjustEvent(adjustment: SliderAdjustment, index: number): SliderAdjustEvent {
  const { kind, large } = adjustment;
  if (kind === "increment") return { type: "THUMB.INCREMENT", index, large };
  if (kind === "decrement") return { type: "THUMB.DECREMENT", index, large };
  if (kind === "min") return { type: "THUMB.SET_MIN", index };
  return { type: "THUMB.SET_MAX", index };
}

const KEY_INTENTS: Readonly<Record<string, SliderIntent>> = {
  ArrowRight: "moveRight",
  ArrowLeft: "moveLeft",
  ArrowUp: "moveUp",
  ArrowDown: "moveDown",
  PageUp: "pageUp",
  PageDown: "pageDown",
  Home: "home",
  End: "end",
};

/** The eight APG keys, mapped onto the same intents the pad produces. */
export function getKeyIntent(key: string): SliderIntent | null {
  return KEY_INTENTS[key] ?? null;
}

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { EngageIntent, IntentScopeHost } from "../../nav";
import type { Direction, InputModality, Orientation } from "../../types";
import type { RangeBounds, RangeMarks, RangePointOptions } from "../../utils/range";

export type SliderThumbAlignment = "contain" | "center";

/** Explicit positions, a count of evenly spaced ticks, or one tick per step. */
export type SliderMarks = RangeMarks;

export type SliderAdjustmentKind = "increment" | "decrement" | "min" | "max";

export interface SliderAdjustment {
  readonly kind: SliderAdjustmentKind;
  readonly large: boolean;
}

/**
 * The eight inputs `resolveDirection` mirrors. Spelled as the engage grammar's own
 * union so the keyboard and the d-pad cannot drift apart: an intent the pad can
 * send is an intent this component answers, and the compiler says so.
 */
export type SliderIntent = EngageIntent;

// Spelled here under the component's own names, defined once in `utils/range`:
// the arithmetic belongs to any bounded-range control, the vocabulary to this one.
/** Everything the constraint arithmetic needs, and nothing else. */
export type SliderRange = RangeBounds;

/** `thumbSize` is 0 under `thumbAlignment: "center"`. */
export type SliderPointOptions = RangePointOptions;

/** The four value events, as one union: a keyboard and a pad both produce them. */
export type SliderAdjustEvent =
  | { type: "THUMB.INCREMENT"; index: number; large: boolean }
  | { type: "THUMB.DECREMENT"; index: number; large: boolean }
  | { type: "THUMB.SET_MIN"; index: number }
  | { type: "THUMB.SET_MAX"; index: number };

/** Always an array, whatever shape the props were given in. */
export interface SliderValueChangeDetails {
  readonly value: number[];
}

export interface SliderValueTextDetails {
  readonly value: number;
  readonly index: number;
}

export interface SliderMachineProps {
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  /** Vertical reads from the bottom — the minimum sits at the foot of the track — and `ArrowUp` still raises the value whatever the direction. */
  readonly orientation?: Orientation | undefined;
  readonly min?: number | undefined;
  readonly max?: number | undefined;
  readonly step?: number | undefined;
  /**
   * PageUp/PageDown and LT/RT. Defaults to a tenth of the range rather than ten
   * steps: on a 0→1000 slider stepping by 1, ten steps is 10, which is useless.
   */
  readonly largeStep?: number | undefined;
  /** The gap adjacent thumbs must keep, counted in steps. Defaults to 0, which lets two thumbs land on the same value. */
  readonly minStepsBetweenThumbs?: number | undefined;
  /** `"contain"` keeps the thumb inside the control; `"center"` overhangs it. */
  readonly thumbAlignment?: SliderThumbAlignment | undefined;
  readonly disabled?: boolean | undefined;
  /** Blocks the pointer, the arrow keys and the pad's engage mode, and unlike `disabled` leaves the thumb focusable and its value submitted. */
  readonly readOnly?: boolean | undefined;
  readonly invalid?: boolean | undefined;
  readonly required?: boolean | undefined;
  /** One hidden input per thumb, so a range slider submits this name once per value. */
  readonly name?: string | undefined;
  readonly form?: string | undefined;
  /** A scalar is accepted for ergonomics; the machine only ever holds an array. */
  readonly value?: number | readonly number[] | undefined;
  readonly defaultValue?: number | readonly number[] | undefined;
  readonly marks?: SliderMarks | undefined;
  /** Pinned to `en-US` rather than read from the browser: a locale resolved from the environment formats the same number differently on the server and the client, and hydration says so. */
  readonly locale?: string | undefined;
  readonly formatOptions?: Intl.NumberFormatOptions | undefined;
  /** Wins over `formatOptions` when present — the whole string, per thumb. */
  readonly getValueText?: ((details: SliderValueTextDetails) => string) | undefined;
  /** Ids of the text describing this control — a `field` supplies them. */
  readonly describedBy?: string | undefined;
  /**
   * Id of the element naming this control, used only when no `label` part is
   * rendered — a `field` supplies its own label's id, because `<label for>`
   * cannot name a `div[role="slider"]`.
   */
  readonly labelledBy?: string | undefined;
  /** The intent bus engage mode pushes its scope onto. `null` disables the pad. */
  readonly intents?: IntentScopeHost | null | undefined;
  readonly onValueChange?: ((details: SliderValueChangeDetails) => void) | undefined;
  /** Once per gesture, with the value the gesture ended on. */
  readonly onValueChangeEnd?: ((details: SliderValueChangeDetails) => void) | undefined;
}

export interface ResolvedSliderMachineProps extends SliderMachineProps {
  readonly orientation: Orientation;
  readonly min: number;
  readonly max: number;
  readonly step: number;
  readonly largeStep: number;
  readonly minStepsBetweenThumbs: number;
  readonly thumbAlignment: SliderThumbAlignment;
  readonly disabled: boolean;
  readonly readOnly: boolean;
  readonly invalid: boolean;
  readonly required: boolean;
  readonly locale: string;
  readonly formatOptions: Intl.NumberFormatOptions;
  readonly intents: IntentScopeHost | null;
}

export interface SliderSchema extends MachineSchema {
  state: "idle" | "focused" | "engaged";
  props: ResolvedSliderMachineProps;
  context: {
    value: number[];
    /** −1 when nothing is focused. */
    focusedIndex: number;
    /**
     * −1 when no drag is in flight. Context and not a state: a drag is concurrent
     * with focus rather than a mode of it, and a flat machine cannot hold both.
     */
    activeIndex: number;
    focusSource: InputModality | null;
    hasLabel: boolean;
  };
  computed: {
    isInteractive: boolean;
    percent: number[];
    valueAsText: string[];
    markValues: number[];
  };
  refs: {
    /** Measured once per gesture, for the `contain` travel. */
    thumbSize: number | null;
    /** The engage snapshot B restores to. */
    entryValue: number[] | null;
  };
  event:
    | SliderAdjustEvent
    | { type: "CONTROL.PRESS"; percent: number; index: number }
    | { type: "THUMB.DRAG"; percent: number }
    | { type: "THUMB.DRAG_END"; moved: boolean }
    | { type: "THUMB.FOCUS"; index: number }
    | { type: "THUMB.BLUR" }
    | { type: "THUMB.ENGAGE"; index: number }
    | { type: "THUMB.RELEASE"; committed: boolean }
    | { type: "VALUE.SET"; value: readonly number[] }
    | { type: "PARTS.SYNC" };
  action:
    | "setValue"
    | "setValueFromPercent"
    | "adjustValue"
    | "startDrag"
    | "endDrag"
    | "setFocusedIndex"
    | "focusThumb"
    | "captureFocusSource"
    | "clearFocusSource"
    | "snapshotValue"
    | "restoreValue"
    | "clearSnapshot"
    | "invokeChangeEnd"
    | "syncParts";
  guard: "isInteractive" | "isDragging" | "canEngage";
  effect:
    | "trackModality"
    | "trackParts"
    | "trackPointer"
    | "captureSelectIntent"
    | "captureEngageIntents";
}

export interface SliderThumbProps {
  readonly index: number;
}

export interface SliderMarkerProps {
  readonly value: number;
}

export interface SliderApi<T extends PropTypes = PropTypes> {
  readonly value: number[];
  /** 0…1 per thumb — the CSS gets the percentage, the consumer gets the ratio. */
  readonly valuePercent: number[];
  readonly valueAsText: string[];
  /** The tick positions `marks` resolves to — what `getMarkerProps` is fed. */
  readonly marks: number[];
  readonly dragging: boolean;
  readonly engaged: boolean;
  readonly disabled: boolean;
  readonly focusedIndex: number;
  /** The modality focus arrived under, or `null` while this is not focused. */
  readonly focusSource: InputModality | null;
  readonly focusVisible: boolean;
  setValue(value: number | readonly number[]): void;
  setValueAtIndex(index: number, value: number): void;
  increment(index?: number): void;
  decrement(index?: number): void;
  getRootProps(): T["element"];
  getLabelProps(): T["element"];
  getValueTextProps(): T["element"];
  getControlProps(): T["element"];
  getTrackProps(): T["element"];
  getRangeProps(): T["element"];
  getThumbProps(props: SliderThumbProps): T["element"];
  getHiddenInputProps(props: SliderThumbProps): T["input"];
  getMarkerGroupProps(): T["element"];
  getMarkerProps(props: SliderMarkerProps): T["element"];
}

/**
 * `<Slider>` — the bare name beside the parts, and the first composed layer over
 * a control whose display is *derived* rather than handed in.
 *
 * Three things a consumer got wrong by hand, and the reason this layer exists:
 *
 * The **thumb count** is read from the value, never asked for. `defaultValue={[20, 80]}`
 * with one `SliderThumb` is a two-value machine wearing a one-handle control: the
 * second value moves and nothing on screen says so. `toValueArray` is the core's
 * own normaliser — the same one the machine initialises with — so the two cannot
 * disagree about how many handles a value implies.
 *
 * **Ticks follow `marks`.** Setting `marks` and rendering no `SliderMarkerGroup`
 * is the slider's version of `loading` without `ButtonLoadingIndicator`: the
 * machine resolves the list, and nothing draws it. Here the group comes with the
 * prop and renders itself.
 *
 * And the **label and the value sit directly under the root**, which is what
 * `_slider.scss` has always drawn: the root is `grid-template-columns: 1fr auto`,
 * `slider:label` starts at column 1 and `slider:value-text` at column 2
 * (`_slider.scss:22-23`, `:48`, `:59`). The story wraps the pair in a flex `<div>`
 * and so spends both columns on one cell — a layout node is exactly what a
 * composed layer may not render, and here the rule and the sheet agree.
 */

import { toValueArray } from "@standarui/core/slider";
import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  SliderControl,
  SliderHiddenInput,
  type SliderHiddenInputProps,
  SliderLabel,
  SliderMarkerGroup,
  SliderRange,
  SliderRoot,
  SliderThumb,
  type SliderThumbProps,
  SliderTrack,
  SliderValueText,
  type UseSliderProps,
} from "./slider";

/**
 * The escape hatch, one entry per part. `thumb` and `hiddenInput` drop `index`:
 * it is the composed layer's to assign — one per value — and a fixed one repeated
 * across handles would hand every thumb the same value.
 */
export interface SliderParts {
  readonly label?: PartProps<"span"> | undefined;
  readonly valueText?: PartProps<"span"> | undefined;
  readonly control?: PartProps<"div"> | undefined;
  readonly track?: PartProps<"div"> | undefined;
  readonly range?: PartProps<"div"> | undefined;
  readonly markerGroup?: PartProps<"div"> | undefined;
  readonly thumb?: Omit<SliderThumbProps, "index"> | undefined;
  readonly hiddenInput?: Omit<SliderHiddenInputProps, "index"> | undefined;
}

export interface SliderComposedProps
  extends UseSliderProps,
    Omit<PartProps<"div", UseSliderProps>, "children"> {
  /** Rendered as `SliderLabel`. Omitted, no label part exists and none is named. */
  readonly label?: ReactNode;
  /**
   * The formatted value, in the second grid column. On by default because the
   * column is reserved whether or not anything fills it, and because the machine
   * has already done the formatting — `locale`, `formatOptions` and `getValueText`
   * all land in it without the consumer touching the string.
   */
  readonly showValue?: boolean | undefined;
  /**
   * Defaults to `true` as soon as `marks` is set, which is the only reading that
   * makes the two props agree. Pass `false` to keep the scale and hide the ticks.
   */
  readonly ticks?: boolean | undefined;
  readonly parts?: SliderParts | undefined;
}

export function Slider(props: SliderComposedProps): ReactNode {
  const { label, showValue = true, ticks, parts, ...rest } = props;
  // The index is the identity here: a thumb has no key of its own, and its
  // position in the value array is what the machine addresses it by.
  const thumbs = toValueArray(rest.value ?? rest.defaultValue).map((_unused, index) => index);
  const showTicks = ticks ?? rest.marks !== undefined;

  return (
    <SliderRoot {...rest}>
      {label === undefined ? null : <SliderLabel {...parts?.label}>{label}</SliderLabel>}
      {showValue ? <SliderValueText {...parts?.valueText} /> : null}
      <SliderControl {...parts?.control}>
        <SliderTrack {...parts?.track}>
          <SliderRange {...parts?.range} />
        </SliderTrack>
        {thumbs.map((index) => (
          <SliderThumb key={index} {...parts?.thumb} index={index} />
        ))}
        {showTicks ? <SliderMarkerGroup {...parts?.markerGroup} /> : null}
      </SliderControl>
      {thumbs.map((index) => (
        <SliderHiddenInput key={index} {...parts?.hiddenInput} index={index} />
      ))}
    </SliderRoot>
  );
}

/**
 * The slider in React: one machine in the root, ten parts that read it.
 *
 * Two things are wired here that a consumer should never have to wire by hand.
 * The field a slider sits in — inherited as machine props, never merged over the
 * output, so a field's `disabled: false` cannot talk over a control that disabled
 * itself. And the intent scope engage mode pushes onto, taken from the nearest
 * `<NavProvider>`, exactly the way the dialog takes the one B travels on.
 *
 * The three indexed parts take their `index` as a prop rather than through a
 * context. A v1 slider has one thumb, so the default is 0 and the single-handle
 * markup never mentions it; when `range-slider` arrives (Phase 7) the same parts
 * take 0 and 1 with nothing new to learn.
 */

import * as slider from "@standarui/core/slider";
import type { ReactNode } from "react";
import { createPart, type PartProps } from "../../create-part";
import { inheritFromField, useFieldContext } from "../../field-context";
import { useIntentScopeHost } from "../../nav";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type SliderApi = slider.SliderApi<ReactPropTypes>;

const SliderContext = createPartContext<SliderApi>("Slider");

export interface UseSliderProps extends slider.SliderMachineProps, MachineRuntimeProps {}

export function useSlider(props: UseSliderProps): SliderApi {
  const host = useIntentScopeHost();

  return slider.connect(
    useMachine(slider.machine, {
      ...props,
      // `??` would override an explicit `null`, and `null` is how a consumer says
      // "this slider answers no gamepad" while a provider is mounted above it.
      intents: props.intents === undefined ? host : props.intents,
    }),
    normalizeProps,
  );
}

/**
 * The api of the slider a subtree sits in — what a consumer reads to lay out the
 * markers (`api.marks`) or to print the formatted value themselves.
 */
export function useSliderContext(): SliderApi {
  return SliderContext.usePart("SliderContext");
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "orientation",
  "min",
  "max",
  "step",
  "largeStep",
  "minStepsBetweenThumbs",
  "thumbAlignment",
  "value",
  "defaultValue",
  "marks",
  "disabled",
  "readOnly",
  "invalid",
  "required",
  "name",
  "form",
  "locale",
  "formatOptions",
  "getValueText",
  "describedBy",
  "labelledBy",
  "intents",
  "onValueChange",
  "onValueChangeEnd",
] as const;

export interface SliderRootProps extends UseSliderProps, PartProps<"div", UseSliderProps> {}

export function SliderRoot(props: SliderRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const field = useFieldContext();
  const api = useSlider(inheritFromField(machineProps, field));

  return (
    <SliderContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </SliderContext.Provider>
  );
}

/**
 * A `span`, and it has to be: `<label for>` only names *labelable* elements, and
 * the thumb is a `div[role="slider"]`. The thumb points back at this instead —
 * but only once the machine has seen the part in the DOM, so an author who omits
 * it never gets a dangling `aria-labelledby`.
 */
export const SliderLabel: (props: PartProps<"span">) => ReactNode = createPart(SliderContext, {
  name: "SliderLabel",
  element: "span",
  props: (api) => api.getLabelProps(),
});

/**
 * Prints the formatted value when given nothing to print, the way
 * `SelectValueText` prints the selected label: the value is derived state, and a
 * part that made every consumer reach for `useSliderContext` to render the one
 * string the machine already formatted would be publishing a chore, not an api.
 * `children` still wins, so a consumer who wants another separator or another
 * shape writes it and nothing here interferes.
 */
export function SliderValueText(props: PartProps<"span">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const api = SliderContext.usePart("SliderValueText");

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getValueTextProps(),
    elementProps,
    children: children ?? api.valueAsText.join(" – "),
  });
}

